from pathlib import Path
import re

root = Path(__file__).resolve().parent.parent
draft = (root / '_WORK/AUTHOR_DRAFT.md').read_text(encoding='utf-8')
text = draft
changes = []

def save_progress():
    snapshot = text
    for name in ('RAW_FACTS.md', 'SOURCES.md', 'OPEN_QUESTIONS.md', 'CRITIC.md'):
        snapshot = snapshot.replace(f'../{name}', name)
    snapshot = snapshot.replace('](CASE_NOTES.md)', '](_WORK/CASE_NOTES.md)')
    (root / 'report_human_case_analytics.md').write_text(snapshot, encoding='utf-8')

save_progress()

def replace(old, new):
    global text
    n = text.count(old)
    if n != 1:
        raise ValueError(f'Expected one occurrence, found {n}: {old[:110]}')
    text = text.replace(old, new, 1)
    changes.append(old[:100])
    save_progress()

def paragraph(prefix, body):
    """Rewrite prose while retaining the paragraph's complete reference tail."""
    matches = [p for p in text.split('\n\n') if p.startswith(prefix)]
    if len(matches) != 1:
        raise ValueError(f'Paragraph match {len(matches)}: {prefix}')
    old = matches[0]
    ref = re.search(r' \[(?:F|Q|S)\d', old)
    if not ref:
        if '[' in old and '[E001–E006]' not in body:
            raise ValueError(f'No terminal reference tail: {prefix}')
        replace(old, body)
    else:
        replace(old, body + old[ref.start():])

